if (root == nullptr) {
    return nullptr;
}

Node* current = root;
while (!current->isLeaf) {
    const std::vector<int>& keys = current->keys;
    const std::vector<Node*>& children = current->ptr2TreeOrData.ptr2Tree;

    // Find the position where the key should be inserted
    auto pos = std::upper_bound(keys.begin(), keys.end(), key) - keys.begin();

    // Ensure the index is within bounds
    if (pos >= static_cast<int>(children.size())) {
        pos = children.size() - 1;
    }

    current = children[pos];
}

return current;
